export default {"id": "04", "title": "九个符号，还原一张布局", "outline": [10, 8], "catalog": {"A": [3, 2], "B": [2, 3], "C": [2, 2], "D": [3, 1], "E": [2, 2]}, "scenes": [{"key": "intro-context", "chapter": 1, "title": "为什么布图要从“表示法”开始", "view": "intro-flow04", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "seconds": 18, "note": "不直接搜坐标：先选表示法，再在编码之间搜索", "say": "布图工具不会在所有坐标组合里直接搜索：空间太大。常见的做法是先选一种表示法，再在表示法的编码之间搜索。切片表达式是最直接的一种：九个符号就能写下一张布局。本课讲清它怎样一步步变回坐标。", "start": 0, "delivery": "reading", "end": 18}, {"key": "intro-task", "chapter": 1, "title": "本课任务：一条完整的解码链", "view": "intro-goal04", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "seconds": 19, "note": "实例：五块硬模块各一次、禁旋转、外框10×8；表达式→树→尺寸→坐标", "say": "本课把一条后缀表达式完整还原成布局：解析、建树、自下而上算尺寸、再自上而下传坐标。五块尺寸、禁旋转和 10×8 外框就在画面下方这条约束里——面积合计 23、外框 80，装不满是正常的。先看一个具体问题：为什么非得从表达式走这一趟，而不能直接去摆坐标？", "start": 18, "delivery": "reading", "end": 40.0}, {"key": "intro-preview", "chapter": 1, "title": "先认识贯穿全课的标准表达式", "view": "board", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "seconds": 15, "note": "A D H B V C V E V 的解码结果：正是前两课的9×3标准布局", "say": "先记住这条标准表达式：A D H B V C V E V。它是本课贯穿的例子，解码结果正是前两课里那张九乘三的合法布局。它哪里容易出错？H 和 V 谁先谁后？我们一步一步看。", "start": 40.0, "delivery": "reading", "end": 55.5}, {"key": "notation", "chapter": 2, "title": "字母表示模块，H、V 表示组合", "view": "notation-cards", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "voice": "encoding", "note": "A—E是模块；H/V是两种切线，不是方向指令", "start": 55.5, "delivery": "voice", "end": 62.478}, {"key": "h-convention", "chapter": 2, "title": "H：第一个区域在下，第二个在上", "view": "hv-cards", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "voice": "guess", "note": "H：宽取最大，高相加", "start": 62.478, "delivery": "voice", "end": 69.602}, {"key": "v-convention", "chapter": 2, "title": "V：第一个区域在左，第二个在右", "view": "v-cards", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "seconds": 12, "note": "V：宽相加，高取最大；先弹出的是第二区域", "say": "V 是垂直切线：第一区域在左，第二区域在右，宽相加、高取最大。和 H 一样，“第一、第二”按弹出顺序定：先弹出的是第二区域，后弹出的、更靠栈底的是第一区域。把这条约定写进代码注释，能省掉很多调试。", "start": 69.602, "delivery": "reading", "end": 86.932}, {"key": "max-add", "chapter": 2, "title": "为什么宽取最大、高相加？", "view": "hv-cards", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "voice": "combine", "note": "A(3×2)在下，D(3×1)在上：宽max(3,3)=3，高2+1=3", "question": {"prompt": "把 A D H 换成 A D V（其余符号先不管），A 和 D 会在什么方向排？", "choices": ["V：A 在左、D 在右，宽相加", "V：A 在上、D 在下", "V 和 H 结果完全一样"], "answer": 0, "replies": ["V 是垂直切线：第一区域在左，第二区域在右，宽相加、高取最大。", "上下排列是 H 的约定；V 沿水平方向排。", "两种切线的合并规则不同：一个宽相加，一个高相加。"]}, "start": 86.932, "delivery": "voice", "end": 94.606}, {"key": "stack-start", "chapter": 3, "title": "从空栈开始：压 A，压 D", "view": "stack", "rows": [["D", 0, 0, 3, 1]], "step": 2, "voice": "push", "note": "读到字母就压栈；D 在栈顶", "start": 94.606, "delivery": "voice", "end": 100.744}, {"key": "stack-combine", "chapter": 3, "title": "遇到 H：弹出两个，合成一个", "view": "stack", "rows": [["A", 0, 0, 3, 2], ["D", 0, 2, 3, 1]], "step": 3, "seconds": 12, "note": "先弹出的是第二区域（D），后弹出的是第一区域（A）", "say": "读到 H，弹出两个区域：先弹出的 D 是第二区域，后弹出的 A 是第一区域。合成一个新区域压回去，尺寸按 H 的规则算：宽取最大、高相加，得到三乘三。栈从两层变一层。", "start": 100.744, "delivery": "reading", "end": 115.574}, {"key": "full-decode", "chapter": 3, "title": "按同样的规则读完九个符号", "view": "stack", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "step": 9, "voice": "full", "note": "最终栈里只剩一个区域：9×3", "start": 115.574, "delivery": "voice", "end": 123.008}, {"key": "decode-steps", "chapter": 3, "title": "九步连起来看", "view": "stack-track", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "seconds": 13, "note": "压字母或“弹二合一”，每步栈深不超过2", "say": "把九步连起来：压A、压D、H合并、压B、V接B、压C、V接C、压E、V接E。每一步要么压入一个模块，要么弹出两个区域、合成一个压回。最后栈里只剩一个区域，尺寸九乘三。栈最深只有两层。", "start": 123.008, "delivery": "reading", "end": 139.178}, {"key": "coords-result", "chapter": 3, "title": "解码坐标：又是那张标准布局", "view": "board", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "seconds": 12, "note": "A(0,0) D(0,2) B(3,0) C(5,0) E(7,0)；盒9×3", "say": "解码得到的坐标：A在(0,0)，D在(0,2)，B在(3,0)，C在(5,0)，E在(7,0)，正好是前两课的标准布局。表达式只记录结构；每个坐标都由组合规则算出，不是背出来的。", "start": 139.178, "delivery": "reading", "end": 155.008}, {"key": "sizes-up", "chapter": 4, "title": "尺寸自下而上汇总", "view": "tree-sizes", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "seconds": 13, "note": "叶子是模块尺寸；每个内部节点按max/相加合成", "say": "同一件事也能按树来看：叶子是模块自己的宽高；每往上走一步，H 或 V 把两个孩子的尺寸合成一个。尺寸自下而上汇总，到根就是九乘三。这就是“算尺寸”这一趟。", "start": 155.008, "delivery": "reading", "end": 168.838}, {"key": "coords-down", "chapter": 4, "title": "坐标自上而下传播", "view": "tree-coords", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "seconds": 14, "note": "根放在原点；V的右孩子挪一个左孩子宽，H的上孩子挪一个下孩子高", "say": "坐标从根往下传：根区域的左下角放在原点。V 的左孩子原地开始，右孩子往右挪一个左孩子的宽；H 的下孩子原地，上孩子往上挪一个下孩子的高。每个模块的落点，都是这条链上多次平移的结果。", "start": 168.838, "delivery": "reading", "end": 184.838}, {"key": "order-matters", "chapter": 4, "title": "两趟顺序，谁依赖谁", "view": "two-orders", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "seconds": 12, "note": "不知道区域尺寸，就不知道兄弟该挪多远", "say": "所以解码有两趟：先自下而上求尺寸，再自上而下传坐标。顺序不能反——不知道子区域的尺寸，就不知道兄弟该挪多远。写程序时两趟可以合并成一遍，但依赖关系不能乱。", "start": 184.838, "delivery": "reading", "end": 198.668}, {"key": "three-checks", "chapter": 5, "title": "一个栈元素，只过了结构检查", "view": "checks-cards", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "voice": "checks", "note": "结构、名称、外框是三道独立的检查", "start": 198.668, "delivery": "voice", "end": 207.158}, {"key": "prefix-condition", "chapter": 5, "title": "前缀条件：读符号时就要查", "view": "prefix-chart", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "seconds": 13, "note": "任何前缀里，运算符数不能追上字母数；A H 读到H时下溢", "say": "第一道结构检查在读符号时做：每遇到 H 或 V，栈里必须已有至少两个区域。换句话说，任何位置上，已读的运算符都不能追上已读的字母。A H 是最短的反例：读 H 时栈里只有一个区域，弹出两个会下溢。别以为字母多就够了——A H D B V C V E V 有五个字母、四个符号，总数正好，可第 2 个记号就是 H，照样当场下溢。", "start": 207.158, "delivery": "reading", "end": 235.328}, {"key": "final-one", "chapter": 5, "title": "读完后还有两条结构检查", "view": "checks-cards", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "seconds": 11, "note": "栈里恰剩一个区域；每个字母恰好出现一次", "say": "读完后还要查两条：栈里恰好剩一个区域，多了说明组合没做完；每个字母恰好出现一次，重复或缺失都不行。这三条全过，才轮到Lab2的几何检查——它们查的是结构，不是位置。", "start": 235.328, "delivery": "reading", "end": 249.998}, {"key": "overflow", "chapter": 6, "title": "语法完全合法，仍可能越界", "view": "board-overflow", "rows": [["A", 0, 0, 3, 2], ["B", 6, 0, 2, 3], ["C", 8, 0, 2, 2], ["D", 3, 0, 3, 1], ["E", 10, 0, 2, 2]], "voice": "overflow", "note": "A D V…排成一行：宽12，超过外框10", "start": 249.998, "delivery": "voice", "end": 256.88}, {"key": "swap-operands", "chapter": 6, "title": "换操作数：尺寸不变，落点变", "view": "board", "rows": [["A", 0, 1, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 0, 3, 1], ["E", 7, 0, 2, 2]], "seconds": 13, "note": "D A H…仍是9×3；但A的y从0变1，D从2变0", "say": "换操作数是另一类编辑。把开头的 A D H 改成 D A H：D 在下、A 在上，区域还是三乘三，整体仍是九乘三；但 A 和 D 的坐标对调了。尺寸相同的两份表达式，可以对应不同的布局。", "question": {"prompt": "D A H B V C V E V 的包围盒尺寸是多少？", "choices": ["9×3，和标准表达式相同", "3×3", "12×3"], "answer": 0, "replies": ["只是A、D上下对调，宽高结构与原来相同。", "3×3只是A、D组合的子区域。", "宽12是第一个H改成V的情形；这里没有改。"]}, "start": 256.88, "delivery": "reading", "end": 273.38}, {"key": "first-cut", "chapter": 7, "title": "切片布局：能找到第一刀", "view": "board-cut", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "cut": "v:3", "seconds": 14, "note": "竖线x=3：左边A、D，右边B、C、E；x=5、x=7也各有一条", "say": "切片表达式能还原什么、不能还原什么？先看标准布局：竖线x=3处一刀下去，不穿过任何模块内部，左边剩A和D，右边是B、C、E——这就是第一刀。x=5和x=7也各有一条。能找到第一刀，才能继续往下切、写成一棵切片树。", "start": 273.38, "delivery": "reading", "end": 292.05}, {"key": "pinwheel", "chapter": 7, "title": "风车布局：每条候选线都被挡住", "view": "pinwheel", "rows": [["P", 0, 0, 3, 2], ["Q", 3, 0, 2, 3], ["R", 2, 3, 3, 2], ["S", 0, 2, 2, 3], ["M", 2, 2, 1, 1]], "outline": [5, 5], "catalog": {"P": [3, 2], "Q": [2, 3], "R": [3, 2], "S": [2, 3], "M": [1, 1]}, "line": "v:2.5", "seconds": 14, "note": "5×5五块风车；x=2.5穿过P、M、R三个模块", "say": "再看这个五块风车：五块正好铺满一个五乘五的方框。试一条竖线，比如x=2.5：它同时穿过P、M、R三个模块的内部。横线也一样。候选切线只可能落在块的边缘位置，而这些位置每一条都会被某个块挡住。", "start": 292.05, "delivery": "reading", "end": 308.88}, {"key": "pinwheel-proof", "chapter": 7, "title": "逐条验证：没有第一刀", "view": "pinwheel-sweep", "rows": [["P", 0, 0, 3, 2], ["Q", 3, 0, 2, 3], ["R", 2, 3, 3, 2], ["S", 0, 2, 2, 3], ["M", 2, 2, 1, 1]], "outline": [5, 5], "catalog": {"P": [3, 2], "Q": [2, 3], "R": [3, 2], "S": [2, 3], "M": [1, 1]}, "seconds": 15, "note": "候选竖线2条、横线2条全部穿过内部→无第一刀→写不出表达式", "say": "把结论钉死：五乘五风车里，内部候选竖线有两条、横线有两条，每一条都穿过某个模块的内部；贴合无缝隙，中间位置也一样。没有第一刀，就不存在对应的切片树。顺便提醒：Lab3那份6×4=24的紧凑见证，同样没有第一刀。这不是巧合——把本课这五块的26880份切片编码全部穷举，最小面积只到25，24一份都写不出来；而B*-tree和序列对都能到24。最紧的布局未必是切片布局。", "start": 308.88, "delivery": "reading", "end": 340.55}, {"key": "edit-neighborhood", "chapter": 8, "title": "表达式编辑，就是搜索的邻居", "view": "edit-cards", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "seconds": 14, "note": "换符号/换操作数/换字母顺序；每改一次重新解码、检查、评价", "say": "把表达式看成一个搜索空间：换一个符号、换两个操作数、交换字母顺序，都是一次“邻居”尝试。每改一次，重新解码、用Lab2检查、用Lab3评价，就得到一个新布局。这套“表示法加邻域”正是Lab7搜索的骨架；本课先把解码这一步做扎实。", "start": 340.55, "delivery": "reading", "end": 360.55}, {"key": "transfer", "chapter": 8, "title": "轮到你：修表达式、重建布局、守住约束", "view": "board", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "voice": "try", "note": "三项实验在下方Lab区；表达式逐步解码可观察栈", "start": 360.55, "delivery": "voice", "end": 368.152}], "chapters": ["为什么从表达式开始", "字母与两种切线", "栈解码九个符号", "尺寸与坐标，两个方向", "三个边界检查", "语法合法，仍可能放不下", "切片表示的范围", "表达式就是搜索邻域"], "duration": 368.152, "readingSeconds": 309.83, "captions": [{"start": 0, "end": 4.695652173913044, "text": "布图工具不会在所有坐标组合里直接搜索：空间太大。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 4.695652173913044, "end": 9.978260869565219, "text": "常见的做法是先选一种表示法，再在表示法的编码之间搜索。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 9.978260869565219, "end": 15.06521739130435, "text": "切片表达式是最直接的一种：九个符号就能写下一张布局。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 15.06521739130435, "end": 18.0, "text": "本课讲清它怎样一步步变回坐标。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 18, "end": 25.158730158730158, "text": "本课把一条后缀表达式完整还原成布局：解析、建树、自下而上算尺寸、再自上而下传坐标。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 25.158730158730158, "end": 34.23809523809524, "text": "五块尺寸、禁旋转和 10×8 外框就在画面下方这条约束里——面积合计 23、外框 80，装不满是正常的。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 34.23809523809524, "end": 40.0, "text": "先看一个具体问题：为什么非得从表达式走这一趟，而不能直接去摆坐标？", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 40.0, "end": 45.166666666666664, "text": "先记住这条标准表达式：A D H B V C V E V。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 45.166666666666664, "end": 50.689655172413794, "text": "它是本课贯穿的例子，解码结果正是前两课里那张九乘三的合法布局。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 50.689655172413794, "end": 52.11494252873563, "text": "它哪里容易出错？", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 52.11494252873563, "end": 54.07471264367816, "text": "H 和 V 谁先谁后？", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 54.07471264367816, "end": 55.5, "text": "我们一步一步看。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 55.5, "end": 62.478, "text": "我们用字母表示模块，用 H 和 V 表示两个区域如何组合。", "delivery": "voice", "sourceKey": "encoding", "words": [{"text": "我们", "start": 55.602083, "end": 55.810416000000004}, {"text": "用", "start": 55.823458, "end": 56.031791}, {"text": "字母", "start": 56.031791, "end": 56.396374}, {"text": "表示", "start": 56.422416, "end": 56.695874}, {"text": "模块", "start": 56.708875, "end": 57.151583}, {"text": "用", "start": 57.594291, "end": 57.854707}, {"text": "H", "start": 57.854708, "end": 58.180249}, {"text": "和", "start": 58.19325, "end": 58.336458}, {"text": "V", "start": 58.336458, "end": 58.505749}, {"text": "表示", "start": 58.51875, "end": 58.883333}, {"text": "两个", "start": 58.909375, "end": 59.195833}, {"text": "区域", "start": 59.208875, "end": 59.651583}, {"text": "如何", "start": 59.677625, "end": 60.016166}, {"text": "组合", "start": 60.029166000000004, "end": 60.497916000000004}]}, {"start": 62.478, "end": 69.602, "text": "H 是水平切线，让第一个区域在下，第二个区域在上。", "delivery": "voice", "sourceKey": "guess", "words": [{"text": "H", "start": 62.580083, "end": 62.99674900000001}, {"text": "是", "start": 62.996750000000006, "end": 63.205083}, {"text": "水平", "start": 63.218125, "end": 63.582708}, {"text": "切线", "start": 63.595708, "end": 64.077499}, {"text": "让", "start": 64.376958, "end": 64.585291}, {"text": "第一个", "start": 64.611333, "end": 64.910833}, {"text": "区域", "start": 64.923833, "end": 65.18424900000001}, {"text": "在", "start": 65.197291, "end": 65.34049900000001}, {"text": "下", "start": 65.3405, "end": 65.653}, {"text": "第二个", "start": 65.926458, "end": 66.2780409}, {"text": "区域", "start": 66.29104099999999, "end": 66.551457}, {"text": "在上", "start": 66.564458, "end": 66.98112400000001}]}, {"start": 69.602, "end": 75.0839387755102, "text": "V 是垂直切线：第一区域在左，第二区域在右，宽相加、高取最大。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 75.0839387755102, "end": 83.39526530612245, "text": "和 H 一样，“第一、第二”按弹出顺序定：先弹出的是第二区域，后弹出的、更靠栈底的是第一区域。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 83.39526530612245, "end": 86.932, "text": "把这条约定写进代码注释，能省掉很多调试。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 86.932, "end": 94.60600000000001, "text": "组合时先弹出 D，再弹出 A；D 放在 A 上面，得到三乘三。", "delivery": "voice", "sourceKey": "combine", "words": [{"text": "组合", "start": 87.03408300000001, "end": 87.42470800000001}, {"text": "时", "start": 87.42470800000001, "end": 87.763249}, {"text": "先", "start": 87.789291, "end": 88.010666}, {"text": "弹出", "start": 88.023666, "end": 88.37524900000001}, {"text": "D", "start": 88.37525000000001, "end": 88.635666}, {"text": "再", "start": 88.883041, "end": 89.052332}, {"text": "弹出", "start": 89.06533300000001, "end": 89.46899900000001}, {"text": "A", "start": 89.46900000000001, "end": 89.846625}, {"text": "D", "start": 90.302333, "end": 90.44558300000001}, {"text": "放", "start": 90.458583, "end": 90.601791}, {"text": "在", "start": 90.601791, "end": 90.705957}, {"text": "A", "start": 90.71900000000001, "end": 90.914291}, {"text": "上面", "start": 90.914291, "end": 91.42212400000001}, {"text": "得到", "start": 91.630458, "end": 91.942958}, {"text": "三乘三", "start": 91.96900000000001, "end": 92.646083}]}, {"start": 94.60600000000001, "end": 100.74400000000001, "text": "先把 A 压入栈，再把 D 压入栈；D 就在栈顶。", "delivery": "voice", "sourceKey": "push", "words": [{"text": "先", "start": 94.70808300000002, "end": 95.00758300000001}, {"text": "把", "start": 95.00758300000001, "end": 95.137791}, {"text": "A", "start": 95.16383300000001, "end": 95.38516600000001}, {"text": "压", "start": 95.38516600000001, "end": 95.59349900000001}, {"text": "入", "start": 95.59350000000002, "end": 95.74975000000002}, {"text": "栈", "start": 95.74975000000002, "end": 96.06225000000002}, {"text": "再", "start": 96.231541, "end": 96.40079100000001}, {"text": "把", "start": 96.40079100000001, "end": 96.51799900000002}, {"text": "D", "start": 96.544041, "end": 96.73937400000001}, {"text": "压", "start": 96.75237500000001, "end": 96.90862500000001}, {"text": "入", "start": 96.90862500000001, "end": 97.02583300000002}, {"text": "栈", "start": 97.03883300000001, "end": 97.33833300000002}, {"text": "D", "start": 97.72891600000001, "end": 98.00237400000002}, {"text": "就", "start": 98.01537500000002, "end": 98.15862500000001}, {"text": "在", "start": 98.15862500000001, "end": 98.262791}, {"text": "栈顶", "start": 98.27579100000001, "end": 98.78362400000002}]}, {"start": 100.74400000000001, "end": 107.53363855421688, "text": "读到 H，弹出两个区域：先弹出的 D 是第二区域，后弹出的 A 是第一区域。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 107.53363855421688, "end": 114.14460240963857, "text": "合成一个新区域压回去，尺寸按 H 的规则算：宽取最大、高相加，得到三乘三。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 114.14460240963857, "end": 115.57400000000001, "text": "栈从两层变一层。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 115.57400000000001, "end": 123.00800000000001, "text": "再用 V 依次接上 B、C 和 E，最终得到九乘三的包围盒。", "delivery": "voice", "sourceKey": "full", "words": [{"text": "再", "start": 115.67608300000002, "end": 115.85837400000001}, {"text": "用", "start": 115.85837500000001, "end": 116.14483300000002}, {"text": "V", "start": 116.17087500000001, "end": 116.431291}, {"text": "依次", "start": 116.44433300000001, "end": 116.71779100000002}, {"text": "接上", "start": 116.730791, "end": 117.18654100000002}, {"text": "B", "start": 117.277666, "end": 117.57716600000002}, {"text": "C", "start": 117.77245800000001, "end": 118.267249}, {"text": "和", "start": 118.28025000000001, "end": 118.462541}, {"text": "E", "start": 118.462541, "end": 118.735999}, {"text": "最终", "start": 119.03545800000002, "end": 119.45212400000001}, {"text": "得到", "start": 119.465166, "end": 119.777666}, {"text": "九乘三", "start": 119.80370800000001, "end": 120.35058300000001}, {"text": "的", "start": 120.35058300000001, "end": 120.441749}, {"text": "包围", "start": 120.45475, "end": 120.75420800000002}, {"text": "盒", "start": 120.75420800000002, "end": 121.05370800000001}]}, {"start": 123.00800000000001, "end": 129.7603076923077, "text": "把九步连起来：压A、压D、H合并、压B、V接B、压C、V接C、压E、V接E。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 129.7603076923077, "end": 134.73569230769232, "text": "每一步要么压入一个模块，要么弹出两个区域、合成一个压回。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 134.73569230769232, "end": 137.75646153846154, "text": "最后栈里只剩一个区域，尺寸九乘三。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 137.75646153846154, "end": 139.178, "text": "栈最深只有两层。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 139.178, "end": 149.84991011235954, "text": "解码得到的坐标：A在(0,0)，D在(0,2)，B在(3,0)，C在(5,0)，E在(7,0)，正好是前两课的标准布局。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 149.84991011235954, "end": 155.00799999999998, "text": "表达式只记录结构；每个坐标都由组合规则算出，不是背出来的。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 155.008, "end": 163.62929870129872, "text": "同一件事也能按树来看：叶子是模块自己的宽高；每往上走一步，H 或 V 把两个孩子的尺寸合成一个。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 163.62929870129872, "end": 166.68267532467536, "text": "尺寸自下而上汇总，到根就是九乘三。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 166.68267532467536, "end": 168.83800000000002, "text": "这就是“算尺寸”这一趟。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 168.83800000000002, "end": 172.39355555555557, "text": "坐标从根往下传：根区域的左下角放在原点。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 172.39355555555557, "end": 180.9268888888889, "text": "V 的左孩子原地开始，右孩子往右挪一个左孩子的宽；H 的下孩子原地，上孩子往上挪一个下孩子的高。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 180.9268888888889, "end": 184.838, "text": "每个模块的落点，都是这条链上多次平移的结果。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 184.83800000000002, "end": 189.50787012987016, "text": "所以解码有两趟：先自下而上求尺寸，再自上而下传坐标。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 189.50787012987016, "end": 194.53696103896107, "text": "顺序不能反——不知道子区域的尺寸，就不知道兄弟该挪多远。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 194.53696103896107, "end": 198.66800000000003, "text": "写程序时两趟可以合并成一遍，但依赖关系不能乱。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 198.66800000000003, "end": 207.15800000000004, "text": "所以一个栈元素只是结构检查通过，不能替代名称检查和外框检查。", "delivery": "voice", "sourceKey": "checks", "words": [{"text": "所以", "start": 198.77008300000003, "end": 199.47320800000003}, {"text": "一个", "start": 199.57737500000005, "end": 199.81175000000005}, {"text": "栈元素", "start": 199.82479100000003, "end": 200.48887400000004}, {"text": "只是", "start": 200.59300000000005, "end": 200.86645800000005}, {"text": "结构", "start": 200.87945800000003, "end": 201.19195800000003}, {"text": "检查", "start": 201.20500000000004, "end": 201.53054100000006}, {"text": "通过", "start": 201.54354100000003, "end": 201.97324900000004}, {"text": "不能", "start": 202.36383300000003, "end": 202.66333300000005}, {"text": "替代", "start": 202.67633300000003, "end": 202.97583300000005}, {"text": "名称", "start": 203.00187500000004, "end": 203.35345800000005}, {"text": "检查", "start": 203.36645800000005, "end": 203.97845800000005}, {"text": "和", "start": 204.08258300000003, "end": 204.26487400000005}, {"text": "外框", "start": 204.27791600000003, "end": 204.65554100000006}, {"text": "检查", "start": 204.66854100000003, "end": 205.18937400000004}]}, {"start": 207.15800000000004, "end": 213.55241717791415, "text": "第一道结构检查在读符号时做：每遇到 H 或 V，栈里必须已有至少两个区域。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 213.55241717791415, "end": 218.3914355828221, "text": "换句话说，任何位置上，已读的运算符都不能追上已读的字母。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 218.3914355828221, "end": 224.09456441717793, "text": "A H 是最短的反例：读 H 时栈里只有一个区域，弹出两个会下溢。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 224.09456441717793, "end": 235.32800000000003, "text": "别以为字母多就够了——A H D B V C V E V 有五个字母、四个符号，总数正好，可第 2 个记号就是 H，照样当场下溢。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 235.32800000000003, "end": 244.09421951219517, "text": "读完后还要查两条：栈里恰好剩一个区域，多了说明组合没做完；每个字母恰好出现一次，重复或缺失都不行。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 244.09421951219517, "end": 249.99800000000005, "text": "这三条全过，才轮到Lab2的几何检查——它们查的是结构，不是位置。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 249.99800000000002, "end": 256.88, "text": "把第一个 H 改成 V，模块排成一行，总宽度变成十二。", "delivery": "voice", "sourceKey": "overflow", "words": [{"text": "把", "start": 250.10008299999998, "end": 250.282374}, {"text": "第一个", "start": 250.295416, "end": 250.65999900000003}, {"text": "H", "start": 250.673, "end": 250.946458}, {"text": "改成", "start": 250.95945799999998, "end": 251.415208}, {"text": "V", "start": 251.415208, "end": 251.844916}, {"text": "模块", "start": 252.092291, "end": 252.430832}, {"text": "排成", "start": 252.45687500000003, "end": 252.782416}, {"text": "一", "start": 252.795416, "end": 252.899582}, {"text": "行", "start": 252.899583, "end": 253.264166}, {"text": "总宽度", "start": 253.4855, "end": 254.149583}, {"text": "变成", "start": 254.149583, "end": 254.436041}, {"text": "十二", "start": 254.44904100000002, "end": 254.91779100000002}]}, {"start": 256.88, "end": 258.8316129032258, "text": "换操作数是另一类编辑。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 258.8316129032258, "end": 269.65419354838707, "text": "把开头的 A D H 改成 D A H：D 在下、A 在上，区域还是三乘三，整体仍是九乘三；但 A 和 D 的坐标对调了。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 269.65419354838707, "end": 273.38, "text": "尺寸相同的两份表达式，可以对应不同的布局。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 273.38, "end": 276.55037735849055, "text": "切片表达式能还原什么、不能还原什么？", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 276.55037735849055, "end": 285.70924528301884, "text": "先看标准布局：竖线x=3处一刀下去，不穿过任何模块内部，左边剩A和D，右边是B、C、E——这就是第一刀。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 285.70924528301884, "end": 287.9989622641509, "text": "x=5和x=7也各有一条。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 287.9989622641509, "end": 292.04999999999995, "text": "能找到第一刀，才能继续往下切、写成一棵切片树。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 292.05, "end": 296.3017894736842, "text": "再看这个五块风车：五块正好铺满一个五乘五的方框。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 296.3017894736842, "end": 301.97084210526316, "text": "试一条竖线，比如x=2.5：它同时穿过P、M、R三个模块的内部。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 301.97084210526316, "end": 303.03378947368424, "text": "横线也一样。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 303.03378947368424, "end": 308.88000000000005, "text": "候选切线只可能落在块的边缘位置，而这些位置每一条都会被某个块挡住。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 308.88, "end": 318.6908152173913, "text": "把结论钉死：五乘五风车里，内部候选竖线有两条、横线有两条，每一条都穿过某个模块的内部；贴合无缝隙，中间位置也一样。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 318.6908152173913, "end": 321.61684782608694, "text": "没有第一刀，就不存在对应的切片树。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 321.61684782608694, "end": 326.9525543478261, "text": "顺便提醒：Lab3那份6×4=24的紧凑见证，同样没有第一刀。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 326.9525543478261, "end": 338.31244565217395, "text": "这不是巧合——把本课这五块的26880份切片编码全部穷举，最小面积只到25，24一份都写不出来；而B*-tree和序列对都能到24。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 338.31244565217395, "end": 340.55, "text": "最紧的布局未必是切片布局。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 340.55, "end": 348.26929824561404, "text": "把表达式看成一个搜索空间：换一个符号、换两个操作数、交换字母顺序，都是一次“邻居”尝试。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 348.26929824561404, "end": 354.409649122807, "text": "每改一次，重新解码、用Lab2检查、用Lab3评价，就得到一个新布局。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 354.409649122807, "end": 360.55, "text": "这套“表示法加邻域”正是Lab7搜索的骨架；本课先把解码这一步做扎实。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 360.55, "end": 368.15200000000004, "text": "在实验里逐个读取符号，观察栈，再试着构造另一种合法摆法。", "delivery": "voice", "sourceKey": "try", "words": [{"text": "在", "start": 360.65208300000006, "end": 360.84741599999995}, {"text": "实验", "start": 360.860416, "end": 361.26408200000003}, {"text": "里", "start": 361.264083, "end": 361.55054099999995}, {"text": "逐个", "start": 361.66770800000006, "end": 362.045333}, {"text": "读取", "start": 362.05833300000006, "end": 362.383874}, {"text": "符号", "start": 362.396875, "end": 362.83958300000006}, {"text": "观察栈", "start": 363.1, "end": 363.803125}, {"text": "再", "start": 364.0245, "end": 364.219833}, {"text": "试", "start": 364.232833, "end": 364.415124}, {"text": "着", "start": 364.415125, "end": 364.51929099999995}, {"text": "构造", "start": 364.532291, "end": 364.93595700000003}, {"text": "另", "start": 364.962, "end": 365.11825}, {"text": "一种", "start": 365.11825, "end": 365.37866599999995}, {"text": "合法", "start": 365.404708, "end": 365.743249}, {"text": "摆法", "start": 365.75625, "end": 366.172916}]}], "cuts": [{"scene": "notation", "sourceKey": "encoding", "sourceStart": 0.0, "sourceEnd": 6.978, "start": 55.5, "end": 62.478}, {"scene": "h-convention", "sourceKey": "guess", "sourceStart": 13.116, "sourceEnd": 20.24, "start": 62.478, "end": 69.602}, {"scene": "max-add", "sourceKey": "combine", "sourceStart": 20.24, "sourceEnd": 27.914, "start": 86.932, "end": 94.60600000000001}, {"scene": "stack-start", "sourceKey": "push", "sourceStart": 6.978, "sourceEnd": 13.116, "start": 94.60600000000001, "end": 100.74400000000001}, {"scene": "full-decode", "sourceKey": "full", "sourceStart": 27.914, "sourceEnd": 35.348, "start": 115.57400000000001, "end": 123.00800000000001}, {"scene": "three-checks", "sourceKey": "checks", "sourceStart": 42.23, "sourceEnd": 50.72, "start": 198.66800000000003, "end": 207.15800000000004}, {"scene": "overflow", "sourceKey": "overflow", "sourceStart": 35.348, "sourceEnd": 42.23, "start": 249.99800000000002, "end": 256.88}, {"scene": "transfer", "sourceKey": "try", "sourceStart": 50.72, "sourceEnd": 58.322, "start": 360.55, "end": 368.15200000000004}], "newSpeech": false, "audioSha256": "a09c7a11e804ee62e00977b275395725b4d48e1073af77c6c8b93ddee8fc55d8", "sourceHashes": {"content/interactive04.mjs": "cac8b5cbd0fa887f1c61600bc82bd0df02896904d7430db58cebfcf66469ae13", "dist/media/04/zh.m4a": "688366e52531c169a6cd19853b1309e6cbc750d7d5ebc8ecd52b2ea420ef3ba3", "dist/media/04/zh.json": "f066bc39fc6e2fd115d176d913d77700f7ff55c0f464a80094ededa267c35277", "dist/assets/slicing04.mjs": "be573c22855f71c306a39a19a3d9d320c706c66828afb9f76d442c5d6d1b9d1f"}};
